import{z as d,x as s,o as i,c as B,q as o,j as m,D as t,d as E,s as n,S as l,b as e}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"Radon–Nikodym 导数","description":"","frontmatter":{"title":"Radon–Nikodym 导数","date":"2026-09-10T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/radon-nikodym.md","filePath":"quant/radon-nikodym.md","lastUpdated":1791063341000}'),A={name:"quant/radon-nikodym.md"};function h(_,a,p,P,x,b){const r=s("Mermaid");return i(),B("div",null,[a[2]||(a[2]=o('<h1 id="radon–nikodym-导数" tabindex="-1">Radon–Nikodym 导数 <a class="header-anchor" href="#radon–nikodym-导数" aria-label="Permalink to &quot;Radon–Nikodym 导数&quot;">​</a></h1><div class="epigraph"><p>若 $Q\\ll P$，存在非负可积的 $\\mathrm d Q/\\mathrm d P$，使 $Q(A)=\\mathbb E_P[1_A\\,\\mathrm d Q/\\mathrm d P]$。换测度就是乘上这个密度再归一。</p><footer>—— 据 Rudin, Real and Complex Analysis；Karatzas and Shreve, 1991, §3.5；Shreve, Stochastic Calculus for Finance II, 第 5 章整理</footer></div><p>上一课<a href="/quant/stopping-optional-sampling">停时与可选抽样</a>仍在同一测度 \\(P\\) 下谈公平。缺口是：定价经常要换一个等价测度，使贴现资产变成鞅。换测度的全部信息压缩成一个随机变量 \\(\\xi=\\mathrm d Q/\\mathrm d P\\)。本课只定义绝对连续、等价与密度过程，不把漂移怎么改写完——那是下一课 Girsanov。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>同一可测空间上可以有许多概率。若 \\(P(A)=0\\Rightarrow Q(A)=0\\)，称 \\(Q\\) 关于 \\(P\\) 绝对连续，记 \\(Q\\ll P\\)。Radon–Nikodym 定理给出密度 \\(\\xi\\ge 0\\)，\\(\\mathbb E_P[\\xi]=1\\)，且 \\(\\mathbb E_Q[X]=\\mathbb E_P[\\xi X]\\)。缺口是把这条定理当成定价运算：期望换测度 = 原测度下乘密度。没有密度，后课「风险中性」只是改写 \\(\\mu\\)，没有概率对象。</p><p>互绝对连续 \\(Q\\sim P\\) 要求两边零集相同，从而 \\(\\xi\\gt 0\\) a.s.，\\(\\mathrm d P/\\mathrm d Q=1/\\xi\\)。定价要等价测度，是为了不把 \\(P\\) 下的不可能事件变成 \\(Q\\) 下的正概率套利通道。</p><p><span class="marginnote">绝对连续（\\(Q\\ll P\\)）翻译成大白话：凡是 P 认为完全不可能发生的事件，Q 也认为不可能。可以想象两张覆盖同一地区的地图，P 画不上点的空白区域，Q 同样画不上点；反过来若双方空白完全一致，就是等价 \\(Q\\sim P\\)。</span></p><h3 id="密度不是似然比的口头禅" tabindex="-1">密度不是似然比的口头禅 <a class="header-anchor" href="#密度不是似然比的口头禅" aria-label="Permalink to &quot;密度不是似然比的口头禅&quot;">​</a></h3><p>统计里的似然比是参数模型下的密度比；这里没有参数，只有两个概率。\\(\\xi\\) 可以是路径泛函，例如指数鞅。把它理解成「参数估计的 LR 检验」，Girsanov 的指数会看起来像假设检验，而不是改漂移。</p><p><span class="marginnote">有限样本空间上 \\(\\xi(\\omega)=Q(\\{\\omega\\})/P(\\{\\omega\\})\\)。连续时间只是把这个比换成 \\(L^1\\) 中的极限对象。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>给定 \\(Q\\ll P\\)，\\(\\xi=\\mathrm d Q/\\mathrm d P\\)。对 \\(\\mathcal F_t\\)-可测有界 \\(X\\)，\\(\\mathbb E_Q[X]=\\mathbb E_P[\\xi X]\\)。定义密度过程 \\(\\xi_t=\\mathbb E_P[\\xi\\mid\\mathcal F_t]\\)，则 \\(\\xi_t\\) 是 \\(P\\)-鞅，且在 \\(\\mathcal F_t\\) 上 \\(\\mathrm d Q/\\mathrm d P|_{\\mathcal F_t}=\\xi_t\\)。Bayes 公式：对 \\(Q\\)-可积 \\(X\\)，</p> \\[\\mathbb E_Q[X\\mid\\mathcal F_t]=\\frac{\\mathbb E_P[\\xi_T X\\mid\\mathcal F_t]}{\\xi_t}\\qquad(t\\le T,\\ \\xi=\\xi_T). \\]<p>这是后课远期测度、改变计价物时换条件期望的唯一规则。</p><p><span class="marginnote">可以把 \\(\\xi_t\\) 想象成两种货币之间的汇率：到时刻 \\(t\\) 为止，把 P 世界的信息换算成 Q 世界要按这个汇率走。Bayes 公式里除以 \\(\\xi_t\\)，相当于把「未来到期的汇率」折回「当前即期汇率」再换算——忘了除以它，条件期望就会系统性算偏。</span></p>',15)),(i(),m(l,null,{default:t(()=>[n(r,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22%E7%89%A9%E7%90%86%E6%B5%8B%E5%BA%A6%20P%22%5D%20--%3E%20XI%5B%22%E5%AF%86%E5%BA%A6%20xi%22%5D%0A%20%20XI%20--%3E%20Q%5B%22%E6%B5%8B%E5%BA%A6%20Q%22%5D%0A%20%20XI%20--%3E%20PROC%5B%22%E5%AF%86%E5%BA%A6%E8%BF%87%E7%A8%8B%E6%98%AF%20P%20%E9%9E%85%22%5D%0A%20%20PROC%20--%3E%20BAYES%5B%22Bayes%EF%BC%9AQ%20%E6%9D%A1%E4%BB%B6%E6%9C%9F%E6%9C%9B%22%5D%0A%20%20BAYES%20--%3E%20GIR%5B%22%E4%B8%8B%E4%B8%80%E8%AF%BE%EF%BC%9AGirsanov%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[E("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"密度过程把「最终换测度」拆到每个 \\(t\\)：到 \\(t\\) 为止已经乘上的因子是 \\(\\xi_t\\)。若 \\(\\xi_t\\) 击中零，等价性在中途破坏。指数鞅保持严格为正，所以 Girsanov 常用它。期望恒等式 \\(\\mathbb E_Q[X]=\\mathbb E_P[\\xi X]\\) 把 \\(Q\\) 下的定价改写成 \\(P\\) 下带权模拟——后课蒙特卡洛的测度变换、重要性采样，用的就是同一条。",-1)),(i(),m(l,null,{default:t(()=>[n(r,{id:"mermaid-48",class:"mermaid",graph:"flowchart%20TD%0A%20%20GOAL%5B%22%E6%83%B3%E7%AE%97%20Q%20%E4%B8%8B%E7%9A%84%E6%9C%9F%E6%9C%9B%20E_Q%5BX%5D%22%5D%20--%3E%20SIM%5B%22%E5%9C%A8%20P%20%E4%B8%8B%E6%A8%A1%E6%8B%9F%E8%B7%AF%E5%BE%84%22%5D%0A%20%20SIM%20--%3E%20XI%5B%22%E5%AF%B9%E6%AF%8F%E6%9D%A1%E8%B7%AF%E5%BE%84%E7%AE%97%E6%9D%83%E9%87%8D%20xi%22%5D%0A%20%20XI%20--%3E%20AVG%5B%22%E5%8F%96%20xi%20%E4%B9%98%20X%20%E7%9A%84%E5%B9%B3%E5%9D%87%22%5D%0A%20%20AVG%20--%3E%20RESULT%5B%22%E5%BE%97%E5%88%B0%20E_Q%5BX%5D%22%5D%0A%20%20XI%20--%3E%20CHECK%7B%22xi%20%E4%BC%9A%E5%8F%96%E5%88%B0%200%20%E5%90%97%22%7D%0A%20%20CHECK%20--%20%22%E4%BC%9A%22%20--%3E%20SING%5B%22%E7%AD%89%E4%BB%B7%E6%80%A7%E7%A0%B4%E5%9D%8F%EF%BC%8C%E4%B8%8D%E8%83%BD%E8%BF%99%E6%A0%B7%E6%8D%A2%22%5D%0A%20%20CHECK%20--%20%22%E4%B8%8D%E4%BC%9A%22%20--%3E%20EXP%5B%22%E6%8C%87%E6%95%B0%E9%9E%85%E4%BF%9D%E6%8C%81%E4%B8%A5%E6%A0%BC%E4%B8%BA%E6%AD%A3%EF%BC%8CGirsanov%20%E9%A6%96%E9%80%89%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=o('<p><span class="marginnote">常见误区：换测度并不是宣称「真实概率变了」。\\(Q\\sim P\\) 下两个测度对「哪些事可能发生」意见一致，只是给各条路径重新分配权重；\\(\\xi\\) 就是这组新权重，且平均权重恒为 1（\\(\\mathbb E_P[\\xi]=1\\)），相当于只挪动筹码、不改赔率结构。</span></p><p>奇异部分：Lebesgue 分解允许 \\(Q\\) 在 \\(P\\) 的零集上仍有质量，那时没有单一密度能捕捉全部 \\(Q\\)。金融主干只用等价测度，奇异换测度不出现。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不证 RN 定理，不讨论无限维空间上的抽象版本。也不引入状态价格密度与 SDF 的经济学语言——那是资产定价实证课的词，这里只保留概率密度。后课默认：\\(Q\\sim P\\) 即存在严格正鞅 \\(\\xi_t\\)；换期望就是乘 \\(\\xi\\)。下一课<a href="/quant/girsanov-measure">Girsanov 测度变换</a>给出布朗运动下 \\(\\xi\\) 的具体形状。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>\\(Q\\ll P\\) 当且仅当存在密度 \\(\\xi=\\mathrm d Q/\\mathrm d P\\)。</li><li>等价要求 \\(\\xi\\gt 0\\)；密度过程 \\(\\xi_t\\) 是 \\(P\\)-鞅。</li><li>\\(Q\\) 下期望 = \\(P\\) 下乘 \\(\\xi\\)；条件期望走 Bayes。</li><li>密度是路径泛函，不是统计检验的口头禅。</li><li>出处：Karatzas–Shreve §3.5；Shreve SDE II 第 5 章。</li></ul>',6))])}const c=d(A,[["render",h]]);export{u as __pageData,c as default};
